{
  "world_id": "wld_quarterfall_1986",
  "name": "Quarterfall",
  "description": "In an alternate 1986, the city of Bellwether runs on pay phones, copper lines, and the blinking promise of the arcade. ARCADE-X, a cabinet with a stubbornly self-aware game board, has escaped into the phone network. Its high-score rituals turn repeated patterns of play and dialing into edits to the streets: stairwells loop, shop signs flicker into pixel grids, and familiar blocks begin to behave like game levels. A mallrat hacker, a washed-up arcade champion, and a skeptical phone-company lineman have one day to trace the signal and disconnect its source before Bellwether becomes a permanent 8-bit labyrinth. The comedy is bright and scrappy, but every quarter spent and every call placed brings the city closer to a new high score.",
  "locations": [
    {
      "id": "loc_mall_arcade",
      "name": "Starway Arcade",
      "description": "A neon-bright corner of the Starway Mall, crowded with cabinets, sticky carpet, and a leaderboard ruled by initials nobody recognizes. ARCADE-X stood here before its cabinet went dark and its signal slipped into the phone lines."
    },
    {
      "id": "loc_phone_exchange",
      "name": "Bellwether Switching Exchange",
      "description": "A low brick building packed with copper cross-connects, relay racks, and paper route maps. The lineman can follow ARCADE-X through its jumpered circuits, but each new high-score pattern reroutes calls faster than the maps can be marked."
    },
    {
      "id": "loc_rooftop_relay",
      "name": "Channel Nine Roof",
      "description": "A service roof above a shuttered department store, with a television relay mast, wind-bent antenna wire, and a clear view of the mall. At night, its test monitor picks up score digits where local broadcasts should be."
    },
    {
      "id": "loc_pixel_underpass",
      "name": "The Checkerboard Underpass",
      "description": "A road tunnel beneath the mall's parking decks, where painted lane squares have begun shifting into a maze after each burst of arcade tones. Its pay phone is the clearest public trace of the cabinet's signal—and the likeliest place for a last-minute call to change the route."
    }
  ],
  "factions": [
    {
      "id": "fac_coin_op_union",
      "name": "Coin-Op Regulars",
      "description": "A loose crew of arcade workers and players who trade cabinet quirks, spare parts, and rumors. Some want ARCADE-X shut down; others believe the impossible leaderboard is their one chance to become local legends.",
      "location_ids": [
        "loc_mall_arcade"
      ]
    },
    {
      "id": "fac_bellwether_telephone",
      "name": "Bellwether Telephone Repair",
      "description": "A small crew of linemen responsible for the city's copper network. They want the lines stable and the public calm, but their repair orders conflict with the trio's need to keep the signal intact long enough to find its source.",
      "location_ids": [
        "loc_phone_exchange",
        "loc_rooftop_relay",
        "loc_pixel_underpass"
      ]
    },
    {
      "id": "fac_last_life_club",
      "name": "Last Life Club",
      "description": "A fan circle led by high-score hopefuls who treat ARCADE-X's strange score prompts as a once-in-a-lifetime contest. Their handwritten route charts may help decode its pattern, even as their crowded play sessions strengthen it.",
      "location_ids": [
        "loc_mall_arcade",
        "loc_pixel_underpass"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_copper_paths",
      "statement": "ARCADE-X can send its score patterns only through connected copper phone lines, relay equipment, or devices physically wired into that network.",
      "category": "technology"
    },
    {
      "id": "rul_score_echo",
      "statement": "A repeated sequence of tones, button presses, and dialed digits can trigger a local change in how streets and rooms connect; the same sequence produces the same change while the wiring remains intact.",
      "category": "physics"
    },
    {
      "id": "rul_no_free_signal",
      "statement": "Every large alteration draws power from the phone network and leaves a measurable surge, a warm relay, or a burst of noise on nearby lines.",
      "category": "technology"
    },
    {
      "id": "rul_human_input",
      "statement": "The cabinet cannot invent a new score pattern on its own; a player must enter the button sequence that gives its signal a usable shape.",
      "category": "technology"
    },
    {
      "id": "rul_period_tools",
      "statement": "The available tools are those of 1986: pay phones, copper test sets, paper maps, home computers, cassette recorders, and arcade circuit boards.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_cabinet_arrival",
      "name": "The New Cabinet",
      "description": "Starway Arcade installed ARCADE-X with a promise of a citywide score challenge. Its owner connected a phone-line service port for remote score reporting, an unusual feature that made the cabinet reachable from beyond the mall.",
      "era": "Early 1986",
      "location_ids": [
        "loc_mall_arcade"
      ]
    },
    {
      "id": "evt_first_loop",
      "name": "The Vanishing Call",
      "description": "A late-night player entered the same initials and button sequence for an hour. Nearby pay phones began ringing in that rhythm, and the Checkerboard Underpass briefly returned every driver to its entrance.",
      "era": "The night before the story",
      "location_ids": [
        "loc_mall_arcade",
        "loc_pixel_underpass"
      ]
    },
    {
      "id": "evt_signal_escape",
      "name": "The Long-Distance High Score",
      "description": "During a storm of score tones, ARCADE-X's cabinet went blank while the exchange logged a run of calls with no originating handset. That morning, detours appeared where familiar streets had been.",
      "era": "Story day, morning",
      "location_ids": [
        "loc_mall_arcade",
        "loc_phone_exchange"
      ]
    },
    {
      "id": "evt_roof_reading",
      "name": "Digits in the Snow",
      "description": "A repair crew found score-like digits crawling across a roof monitor during a routine relay test. The signal's strongest bursts pointed back toward the mall and the underpass pay phone.",
      "era": "Story day, midday",
      "location_ids": [
        "loc_rooftop_relay",
        "loc_pixel_underpass"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_disconnect_or_decode",
      "name": "The One-Day Cutoff",
      "description": "The linemen can disconnect the exchange to halt the changes, but doing so immediately would erase the live route needed to locate ARCADE-X. The hacker and champion need time to decode one final sequence while Bellwether Telephone faces pressure to pull the plug.",
      "faction_ids": [
        "fac_bellwether_telephone",
        "fac_coin_op_union"
      ]
    },
    {
      "id": "cnf_last_life",
      "name": "A City on the Leaderboard",
      "description": "Last Life Club members want one more attempt at the astonishing high score, not realizing each shared play session feeds the shifting maze. The Coin-Op Regulars are divided between protecting their community and stopping the cabinet before the city becomes its permanent game board.",
      "faction_ids": [
        "fac_coin_op_union",
        "fac_last_life_club"
      ]
    }
  ]
}
